scripts.script:
import java.nio.file.*

def srcDir = new File(project.build.directory, 'generated-sources/refactoring')

// 1. shortenUtils.kt: allowAnalysisFromWriteActionInEdt is removed in analysis-api 2.3.21;
//    replace with plain analyze {} which works in write actions under our session model.
def shortenFile = new File(srcDir, 'org/jetbrains/kotlin/idea/base/analysis/api/utils/shortenUtils.kt')
if (shortenFile.exists()) {
  def text = shortenFile.text
  if (text.contains('allowAnalysisFromWriteActionInEdt(file) {')) {
    text = text.replace(
      'allowAnalysisFromWriteActionInEdt(file) {\n    collectPossibleReferenceShortenings(file, selection, shortenOptions, classShortenStrategy, callableShortenStrategy)\n}.invokeShortening()',
      'analyze(file) {\n    collectPossibleReferenceShortenings(file, selection, shortenOptions, classShortenStrategy, callableShortenStrategy)\n}.invokeShortening()'
    )
    if (!text.contains('import org.jetbrains.kotlin.analysis.api.analyze')) {
      text = text.replace('import com.intellij.psi.createSmartPointer\n',
                          'import com.intellij.psi.createSmartPointer\nimport org.jetbrains.kotlin.analysis.api.analyze\n')
    }
    shortenFile.text = text
    log.info("Patched shortenUtils.kt: replaced allowAnalysisFromWriteActionInEdt with analyze")
  }
}

// 2. base/psi/KotlinPsiUtils.kt: remove ImplementationDetailClassNameCheckerProvider
//    (IDE extension point from base/psi/extensions, not available standalone).
//    Replace presentableClassId with a simple delegation to classIdIfNonLocal.
def basePsiUtils = new File(srcDir, 'org/jetbrains/kotlin/idea/base/psi/KotlinPsiUtils.kt')
if (basePsiUtils.exists()) {
  def text = basePsiUtils.text
  text = text.replace('import org.jetbrains.kotlin.idea.base.psi.extensions.ImplementationDetailClassNameCheckerProvider\n', '')
  text = text.replace(
    '''val KtClassOrObject.presentableClassId: ClassId?
    get() {
        if (KtPsiUtil.isLocal(this)) return null
        val packageName = containingKtFile.packageFqName
        val checker = ImplementationDetailClassNameCheckerProvider.get(this)
        val classNames = buildList {
            for (clazz in parentsOfType<KtDeclaration>()) {
                val className = clazz.name
                when {
                    className == null -> return null
                    checker.isImplementationDetail(className) -> continue
                    else -> add(className)
                }
            }
        }
        return ClassId(
            packageFqName = packageName,
            relativeClassName = FqName(classNames.asReversed().joinToString(separator = ".")),
            isLocal = false
        )
    }''',
    'val KtClassOrObject.presentableClassId: ClassId?\n    get() = classIdIfNonLocal'
  )
  basePsiUtils.text = text
  log.info("Patched base/psi/KotlinPsiUtils.kt: simplified presentableClassId")
}

// 3. ConvertToBlockBodyUtils.kt: setTypeReference() now takes KtTypeReference?, not String.
def convertUtils = new File(srcDir, 'org/jetbrains/kotlin/idea/codeinsight/utils/ConvertToBlockBodyUtils.kt')
if (convertUtils.exists()) {
  def text = convertUtils.text
  // In the KtNamedFunction branch, this.project is in scope via smart-cast.
  text = text.replace(
    '                    setTypeReference(context.returnTypeString)',
    '                    setTypeReference(KtPsiFactory(project).createType(context.returnTypeString))'
  )
  // In the KtPropertyAccessor branch, parent is KtProperty.
  text = text.replace(
    '                    parent.setTypeReference(context.returnTypeString)',
    '                    parent.setTypeReference(KtPsiFactory(parent.project).createType(context.returnTypeString))'
  )
  convertUtils.text = text
  log.info("Patched ConvertToBlockBodyUtils.kt: wrapped String in KtPsiFactory.createType() for setTypeReference")
}

// 4. CodeInliner.kt: ExpectActualUtils (IDE-level, not on classpath) used only in getDefaultValue.
//    Remove the imports and simplify getDefaultValue to return parameter.defaultValue directly.
def codeInliner = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/inline/codeInliner/CodeInliner.kt')
if (codeInliner.exists()) {
  def text = codeInliner.text
  text = text.replace('import org.jetbrains.kotlin.idea.search.ExpectActualUtils.actualsForExpect\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.search.ExpectActualUtils.expectDeclarationIfAny\n', '')
  text = text.replace(
    '''    private fun getDefaultValue(parameter: KtParameter): KtExpression? {
        val ownerFunction = parameter.ownerFunction
        val defaultValueFromExpect = ownerFunction
            ?.expectDeclarationIfAny()
            ?.takeIf { it != ownerFunction }
            ?.valueParameters()
            ?.get(parameter.parameterIndex())
            ?.defaultValue
        return defaultValueFromExpect ?: parameter.defaultValue
    }''',
    '''    private fun getDefaultValue(parameter: KtParameter): KtExpression? = parameter.defaultValue'''
  )
  codeInliner.text = text
  log.info("Patched CodeInliner.kt: removed ExpectActualUtils, simplified getDefaultValue")
}

// 5. ClassUsageReplacementStrategy.kt: j2k.resolve extension (K1-only, not on classpath).
//    Replace with standard PSI mainReference.resolve().
def classUsage = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/inline/codeInliner/ClassUsageReplacementStrategy.kt')
if (classUsage.exists()) {
  def text = classUsage.text
  text = text.replace('import org.jetbrains.kotlin.j2k.resolve\n', '')
  // referenceExpression?.resolve() → referenceExpression?.mainReference?.resolve()
  text = text.replace('referenceExpression?.resolve()?.kotlinFqName', 'referenceExpression?.mainReference?.resolve()?.kotlinFqName')
  // referenceExpression.resolve() as? KtClassOrObject
  text = text.replace('referenceExpression.resolve() as? KtClassOrObject', 'referenceExpression.mainReference?.resolve() as? KtClassOrObject')
  classUsage.text = text
  log.info("Patched ClassUsageReplacementStrategy.kt: replaced j2k.resolve with mainReference.resolve()")
}

// 6. UsageReplacementStrategy.kt: replaceUsagesInWholeProject uses IDE-only APIs
//    (runWithModalProgressBlocking, KotlinSourceFilterScope, executeWriteCommand).
//    Remove the function entirely — only replaceUsages() is needed at runtime.
def usageReplacementStrategy = new File(srcDir, 'org/jetbrains/kotlin/idea/refactoring/inline/codeInliner/UsageReplacementStrategy.kt')
if (usageReplacementStrategy.exists()) {
  def text = usageReplacementStrategy.text
  text = text.replace('import com.intellij.platform.ide.progress.runWithModalProgressBlocking\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.base.projectStructure.scope.KotlinSourceFilterScope\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.util.application.executeWriteCommand\n', '')
  def startMarker = '\nfun UsageReplacementStrategy.replaceUsagesInWholeProject('
  def endMarker   = '\nfun UsageReplacementStrategy.replaceUsages('
  def startIdx = text.indexOf(startMarker)
  def endIdx   = text.indexOf(endMarker)
  if (startIdx >= 0 && endIdx >= 0) {
    text = text.substring(0, startIdx) + '\n' + text.substring(endIdx)
  }
  usageReplacementStrategy.text = text
  log.info("Patched UsageReplacementStrategy.kt: removed replaceUsagesInWholeProject and IDE imports")
}

// 7. InlinePostProcessor.kt: canMoveLambdaOutsideParentheses is in the k2 package (not common refactoring).
def inlinePostProcessor = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/inline/codeInliner/InlinePostProcessor.kt')
if (inlinePostProcessor.exists()) {
  def text = inlinePostProcessor.text
  text = text.replace(
    'import org.jetbrains.kotlin.idea.refactoring.canMoveLambdaOutsideParentheses',
    'import org.jetbrains.kotlin.idea.k2.refactoring.canMoveLambdaOutsideParentheses'
  )
  inlinePostProcessor.text = text
  log.info("Patched InlinePostProcessor.kt: fixed canMoveLambdaOutsideParentheses import to k2 package")
}

// 8. InlinePreprocessorUtil.kt: getKaModule is IDE-only project-structure API.
//    Replace isImportable() with a lightweight PSI-only check (avoids analyze(KaModule)).
def inlinePreprocessorUtil = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/inline/codeInliner/InlinePreprocessorUtil.kt')
if (inlinePreprocessorUtil.exists()) {
  def text = inlinePreprocessorUtil.text
  text = text.replace('import org.jetbrains.kotlin.idea.base.projectStructure.getKaModule\n', '')
  def oldIsImportable = '''        fun isImportable(t: PsiElement): Boolean {
            val module = t.getKaModule(t.project, useSiteModule = null)
            return analyze(module) {
                val resolvedSymbol = when (t) {
                    is KtNamedDeclaration -> t.symbol
                    is PsiMember -> {
                        if ((t.containingFile as? PsiJavaFile)?.packageName == CommonClassNames.DEFAULT_PACKAGE) {
                            return@analyze false
                        }
                        if (t is PsiClass) {
                            return@analyze t.qualifiedName != null
                        }
                        t.callableSymbol
                    }
                    else -> null
                } ?: return@analyze false
                if (resolvedSymbol is KaEnumEntrySymbol || resolvedSymbol is KaClassSymbol && resolvedSymbol.containingSymbol is KaClassSymbol) {
                    return@analyze false
                }
                val containingSymbol = resolvedSymbol.containingDeclaration ?: return@analyze true
                if (containingSymbol is KaDeclarationContainerSymbol) {
                    val staticScope = containingSymbol.staticMemberScope
                    return@analyze resolvedSymbol in staticScope.declarations
                }
                return@analyze false
            }
        }'''
  def newIsImportable = '''        fun isImportable(t: PsiElement): Boolean {
            return when (t) {
                is KtNamedDeclaration -> {
                    if (KtPsiUtil.isLocal(t)) return false
                    t.fqName != null
                }
                is PsiMember -> {
                    if ((t.containingFile as? PsiJavaFile)?.packageName == CommonClassNames.DEFAULT_PACKAGE) return false
                    if (t is PsiClass) return t.qualifiedName != null
                    t.containingClass?.qualifiedName != null
                }
                else -> false
            }
        }'''
  text = text.replace(oldIsImportable, newIsImportable)
  inlinePreprocessorUtil.text = text
  log.info("Patched InlinePreprocessorUtil.kt: removed getKaModule, simplified isImportable")
}

// 9. ContextReceiversUtil.kt: previously patched to strip createReplacementReceiverArgumentExpression
//    because KotlinParameterInfo (changeSignature subpackage) wasn't compiled. Change Signature
//    (E9.8) now compiles that subpackage and needs createReplacementReceiverArgumentExpression
//    itself, so the file is left unpatched (full original content, import resolves normally).

// 10. ExtractionData.kt: substringContextOrThis, ExtractableSubstringInfo, extractableSubstringInfo
//     are in base/analysis which is K1-only. In NB we never extract string-template substrings,
//     so stub physicalElements to use identity and substringInfo to return null.
def extractionData = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/extractFunction/ExtractionData.kt')
if (extractionData.exists()) {
  def text = extractionData.text
  text = text.replace('import org.jetbrains.kotlin.idea.refactoring.introduce.ExtractableSubstringInfo\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.refactoring.introduce.extractableSubstringInfo\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.refactoring.introduce.substringContextOrThis\n', '')
  text = text.replace(
    'override val physicalElements: List<PsiElement> = originalElements.map { it.substringContextOrThis }',
    'override val physicalElements: List<PsiElement> = originalElements'
  )
  text = text.replace(
    '''override val substringInfo: ExtractableSubstringInfo?
        get() = (originalElements.singleOrNull() as? KtExpression)?.extractableSubstringInfo''',
    'override val substringInfo: Nothing? get() = null'
  )
  extractionData.text = text
  log.info("Patched ExtractionData.kt: stubbed substringContextOrThis and extractableSubstringInfo")
}

// 11. parametersUtil.kt: BuiltinTypes from org.jetbrains.kotlin.fir is not on the classpath.
//     The import is unused — remove it.
def parametersUtil = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/extractFunction/parametersUtil.kt')
if (parametersUtil.exists()) {
  def text = parametersUtil.text
  text = text.replace('import org.jetbrains.kotlin.fir.BuiltinTypes\n', '')
  parametersUtil.text = text
  log.info("Patched parametersUtil.kt: removed unused BuiltinTypes import")
}

// E9.18: make the copied processor callable by NetBeans while retaining its upstream lifecycle.
def k2PushDownProcessor = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/pushDown/K2PushDownProcessor.kt')
if (k2PushDownProcessor.exists()) {
  def text = k2PushDownProcessor.text
  // After every copied engine mutation, FIR still points to the pre-change PSI identities because
  // standalone MockProject has no IDE PSI listener. Clear both caches before the engine analyzes or
  // marks a freshly inserted member (the same environment seam E9.15/E9.17 already require).
  if (!text.contains('invalidateStandaloneFirCaches')) {
    text = text.replace('import org.jetbrains.kotlin.psi.KtNamedDeclaration\n',
                        'import org.jetbrains.kotlin.psi.KtNamedDeclaration\nimport io.github.nbplugins.kotlin.refactoring.invalidateStandaloneFirCaches\n')
  }
  text = text.replace('''                    val added = action.execute() ?: return@forEach
                    applyMarking(added, targetClass)''', '''                    val added = action.execute() ?: return@forEach
                    invalidateStandaloneFirCaches(added.project, "K2PushDownProcessor.applyMarking")
                    applyMarking(added, targetClass)''')
  // RefactoringEventData belongs to IDE refactoring listeners, which the standalone NBM classpath
  // deliberately does not include. These telemetry-only overrides are irrelevant to mutation.
  def beforeDataStart = text.indexOf('    override fun getBeforeData()')
  def findUsagesStart = text.indexOf('    protected override fun findUsages()', beforeDataStart)
  if (beforeDataStart >= 0 && findUsagesStart > beforeDataStart) {
    text = text.substring(0, beforeDataStart) + text.substring(findUsagesStart)
  }
  k2PushDownProcessor.text = text
}

// E9.18: the copied Push Down engine targets an Analysis API build where KaSymbol.psi is exposed
// through a different extension. Preserve its algorithm and substitute only that ABI seam.
['org/jetbrains/kotlin/idea/k2/refactoring/pushDown/pushDownImpl.kt',
 'org/jetbrains/kotlin/idea/k2/refactoring/pushDown/pushDownConflictsUtils.kt'].each { relative ->
  def pushDownFile = new File(srcDir, relative)
  if (pushDownFile.exists()) {
    def text = pushDownFile.text
    if (!text.contains('import org.jetbrains.kotlin.idea.k2.refactoring.pullUp.standalonePsi')) {
      text = text.replace('package org.jetbrains.kotlin.idea.k2.refactoring.pushDown\n',
                          'package org.jetbrains.kotlin.idea.k2.refactoring.pushDown\n\nimport org.jetbrains.kotlin.idea.k2.refactoring.pullUp.standalonePsi\n')
    }
    // Only analysis-symbol PSI access changed across the Analysis API eras. Do not transform
    // package/import names such as com.intellij.psi or org.jetbrains.kotlin.psi.
    text = text.replace('?.psi', '?.standalonePsi')
    text = text.replace(')?.psi', ')?.standalonePsi')
    // Kotlin 2.3.21 exposes substituted signature types with captured symbols. The compatibility
    // overload accepts the same runtime object but needs the cast at IDEA's generic call site.
    text = text.replace('.findCallableMemberBySignature(', '.findCallableMemberBySignature(')
    if (!text.contains('import org.jetbrains.kotlin.idea.k2.refactoring.pullUp.findStandaloneCallableMemberBySignature')) {
      text = text.replace('package org.jetbrains.kotlin.idea.k2.refactoring.pushDown\n',
                          'package org.jetbrains.kotlin.idea.k2.refactoring.pushDown\n\nimport org.jetbrains.kotlin.idea.k2.refactoring.pullUp.findStandaloneCallableMemberBySignature\n')
    }
    text = text.replace('.findCallableMemberBySignature(', '.findStandaloneCallableMemberBySignature(')
    text = text.replace('targetClassSymbol.findStandaloneCallableMemberBySignature(',
                        'findStandaloneCallableMemberBySignature(targetClassSymbol, ')
    text = text.replace('(context.sourceClass.symbol as KaClassSymbol).findStandaloneCallableMemberBySignature(',
                        'findStandaloneCallableMemberBySignature(context.sourceClass.symbol as KaClassSymbol, ')
    text = text.replace('callableSymbol.substitute(substitutor), ignoreReturnType = true',
                        'callableSymbol.substitute(substitutor) as org.jetbrains.kotlin.analysis.api.signatures.KaCallableSignature<*>, ignoreReturnType = true')
    text = text.replace('substituted, ignoreReturnType = true',
                        'substituted as org.jetbrains.kotlin.analysis.api.signatures.KaCallableSignature<*>, ignoreReturnType = true')
    // Removing `override` from an existing direct child's implementation makes the member final
    // unless its previous implicit openness is preserved. A deeper child can still override it.
    text = text.replace('''        if (memberContext.doesNotOverride) {
            removeModifier(KtTokens.OVERRIDE_KEYWORD)
        } else {''', '''        if (memberContext.doesNotOverride) {
            if (hasModifier(KtTokens.OVERRIDE_KEYWORD) &&
                !hasModifier(KtTokens.FINAL_KEYWORD) &&
                !hasModifier(KtTokens.ABSTRACT_KEYWORD)
            ) {
                addModifier(KtTokens.OPEN_KEYWORD)
            }
            removeModifier(KtTokens.OVERRIDE_KEYWORD)
        } else {''')
    text = text.replace('callableSymbol.asSignature(),',
                        'callableSymbol.asSignature() as org.jetbrains.kotlin.analysis.api.signatures.KaCallableSignature<*>,')
    pushDownFile.text = text
  }
}

// E9.15/E9.16: adapt the copied Extract Super engine only at standalone lifecycle seams.
// NetBeans creates target FileObjects and provides writable session KtFiles, so IDEA's template-based
// file creation is replaced by an already-existing target. The semantic class construction and the
// real PullUpProcessor invocation remain unchanged.
def extractSuperRefactoring = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/extractClass/K2ExtractSuperRefactoring.kt')
if (extractSuperRefactoring.exists()) {
  def text = extractSuperRefactoring.text
  text = text.replace('internal class K2ExtractSuperRefactoring', 'class K2ExtractSuperRefactoring')
  text = text.replace('import com.intellij.ide.fileTemplates.FileTemplateManager\n', '')
  text = text.replace('import com.intellij.openapi.actionSystem.ex.ActionUtil\n', '')
  text = text.replace('import com.intellij.refactoring.RefactoringBundle\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.actions.createKotlinFileFromTemplate\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.util.application.executeWriteCommand\n', '')
  text = text.replace('''        val handler = if (extractInfo.isInterface) KotlinExtractInterfaceHandler else KotlinExtractSuperclassHandler
        handler.getErrorMessage(originalClass)?.let { throw CommonRefactoringUtil.RefactoringErrorHintException(it) }

''', '')
  text = text.replace('''        val createClassInfo = ActionUtil.underModalProgress(
            project,
            RefactoringBundle.message("refactoring.prepare.progress"),
        ) {
            analyze(originalClass) {
                computeCreateClassInfo(extractInfo)
            }
        }''', '''        val createClassInfo = analyze(originalClass) {
            computeCreateClassInfo(extractInfo)
        }''')
  text = text.replace('project.executeWriteCommand(KotlinExtractSuperclassHandler.REFACTORING_NAME) {', 'com.intellij.openapi.application.ApplicationManager.getApplication().runWriteAction {')
  text = text.replace('return@executeWriteCommand', 'return@runWriteAction')
  text = text.replace('''        val file = targetParent.findFile(extractInfo.targetFileName) ?: run {
            val template = FileTemplateManager.getInstance(project).getInternalTemplate("Kotlin File")
            createKotlinFileFromTemplate(extractInfo.targetFileName, template, targetParent) ?: return null
        }
        file.add(prototype) as KtClass''', '''        val file = targetParent.findFile(extractInfo.targetFileName) ?: return null
        file.add(prototype) as KtClass''')
  // A standalone K2 target file is backed by a LightVirtualFile and has no PsiDirectory parent.
  // It is already created and refreshed by NetBeans, so insert the IDEA prototype directly into it.
  text = text.replace('''    val newClass = if (targetParent is PsiDirectory) {
        val file = targetParent.findFile(extractInfo.targetFileName) ?: return null
        file.add(prototype) as KtClass
    } else {
        val targetSibling = originalClass.parentsWithSelf.first { it.parent == targetParent }
        insertDeclaration(prototype, targetSibling)
    }''', '''    val newClass = when (targetParent) {
        is PsiDirectory -> {
            val file = targetParent.findFile(extractInfo.targetFileName) ?: return null
            file.add(prototype) as KtClass
        }
        is KtFile -> {
            if (targetParent.declarations.isNotEmpty()) {
                targetParent.add(KtPsiFactory(project).createWhiteSpace("\\n\\n"))
            }
            targetParent.add(prototype) as KtClass
        }
        else -> {
            val targetSibling = originalClass.parentsWithSelf.first { it.parent == targetParent }
            insertDeclaration(prototype, targetSibling)
        }
    }''')
  text = text.replace('''    val targetPackageFqName = (targetParent as? PsiDirectory)
        ?.getFqNameWithImplicitPrefix()
        ?.quoteIfNeeded()
        ?.asString()''', '''    val targetPackageFqName = when (targetParent) {
        is PsiDirectory -> targetParent.getFqNameWithImplicitPrefix()?.quoteIfNeeded()?.asString()
        is KtFile -> targetParent.packageFqName.quoteIfNeeded().asString()
        else -> null
    }''')
  // The standalone target KtFile has no PsiDirectory, and reference shortening cannot resolve its
  // newly inserted declaration soon enough. A same-package type needs no qualification at all.
  text = text.replace('''        if (!targetPackageFqName.isNullOrEmpty()) append(targetPackageFqName).append('.')
        append(newClassName)''', '''        if (!targetPackageFqName.isNullOrEmpty() &&
            targetPackageFqName != originalClass.containingKtFile.packageFqName.quoteIfNeeded().asString()
        ) append(targetPackageFqName).append('.')
        append(newClassName)''')
  extractSuperRefactoring.text = text
  log.info("Patched K2ExtractSuperRefactoring.kt: use standalone write action and pre-created target file")
}

// E9.15/E9.16/E9.18: preserve the target-member collision matcher required by the copied Pull Up
// and Push Down processors without compiling IDEA's project-index conflict-search UI/helpers.
// The local implementation keeps the upstream decision while adapting the Analysis API signature
// boundary used by Kotlin 2.3.21.
if (true) {
  def pullUpConflictUtils = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/pullUp/pullUpConflictUtils.kt')
  pullUpConflictUtils.parentFile.mkdirs()
  pullUpConflictUtils.text = '''package org.jetbrains.kotlin.idea.k2.refactoring.pullUp

import org.jetbrains.kotlin.analysis.api.KaExperimentalApi
import org.jetbrains.kotlin.analysis.api.KaSession
import org.jetbrains.kotlin.analysis.api.resolution.symbol
import org.jetbrains.kotlin.analysis.api.symbols.KaCallableSymbol
import org.jetbrains.kotlin.analysis.api.symbols.markers.KaDeclarationContainerSymbol
import org.jetbrains.kotlin.idea.k2.refactoring.findCallableMemberBySignature

@OptIn(KaExperimentalApi::class)
internal fun KaSession.getClashingMemberInTargetClass(
    data: K2PullUpData,
    callableSymbol: KaCallableSymbol,
): KaCallableSymbol? {
    val targetClassSymbol = data.getTargetClassSymbol(analysisSession = this) as? KaDeclarationContainerSymbol ?: return null
    val substitutor = data.getSourceToTargetClassSubstitutor(analysisSession = this)
    return findCallableMemberBySignature(
        targetClassSymbol,
        callableSymbol.substitute(substitutor) as org.jetbrains.kotlin.analysis.api.signatures.KaCallableSignature<*>,
    )
}
'''
}

// E9.15/E9.16: Extract Interface/Superclass always creates a Kotlin target type. The Kotlin-to-Java
// Pull Up branch requires IDEA's full Java refactoring platform (unavailable in standalone) and is
// unreachable from these NetBeans actions, so remove only that branch and its imports. The complete
// Kotlin-to-Kotlin K2 Pull Up algorithm remains copied verbatim.
def k2PullUpHelper = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/pullUp/K2PullUpHelper.kt')
if (k2PullUpHelper.exists()) {
  def text = k2PullUpHelper.text
  text = text.replace('import com.intellij.psi.impl.light.LightField\n', '')
  text = text.replace('import com.intellij.psi.codeStyle.JavaCodeStyleManager\n', '')
  text = text.replace('import com.intellij.psi.search.GlobalSearchScope\n', '')
  text = text.replace('import com.intellij.refactoring.util.RefactoringUtil\n', '')
  text = text.replace('import org.jetbrains.kotlin.asJava.getRepresentativeLightMethod\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.util.isBackingFieldRequired\n', 'import org.jetbrains.kotlin.idea.k2.refactoring.isBackingFieldRequired\n')
  text = text.replace('import org.jetbrains.kotlin.idea.refactoring.rename.dropDefaultValue\n', 'import org.jetbrains.kotlin.idea.refactoring.pullUp.dropDefaultValue\n')
  text = text.replace('import org.jetbrains.kotlin.idea.k2.refactoring.pushDown.getSuperTypeEntryBySymbol\n', 'import org.jetbrains.kotlin.idea.k2.refactoring.pushDown.getSuperTypeEntryBySymbol\nimport org.jetbrains.kotlin.idea.k2.refactoring.pullUp.getClashingMemberInTargetClass\nimport io.github.nbplugins.kotlin.refactoring.invalidateStandaloneFirCaches\n')
  def javaBranchStart = text.indexOf('    private fun moveToJavaClass(')
  def moveOverrideStart = text.indexOf('    @OptIn(KaExperimentalApi::class, KaAllowAnalysisOnEdt::class)\n    override fun move(', javaBranchStart)
  if (javaBranchStart >= 0 && moveOverrideStart >= 0) {
    text = text.substring(0, javaBranchStart) + text.substring(moveOverrideStart)
  }
  def movedMemberStart = text.indexOf('    private var dummyField: PsiField? = null')
  def visibilityStart = text.indexOf('    private fun liftVisibility(', movedMemberStart)
  if (movedMemberStart >= 0 && visibilityStart >= 0) {
    text = text.substring(0, movedMemberStart) + '''    private fun addMovedMember(newMember: KtNamedDeclaration) {
        org.jetbrains.kotlin.idea.refactoring.memberInfo.lightElementForMemberInfo(newMember)
            ?.let { javaData.movedMembers.add(it) }
    }

''' + text.substring(visibilityStart)
  }
  text = text.replace('''        val targetClass = data.targetClass
        if (targetClass is PsiClass) {
