// 18. K2MoveTargetDescriptor.kt (E9.7): DirectoryUtil/VfsUtilCore (com.intellij.ide.util /
//     com.intellij.openapi.vfs) are not on our minimal core/core-impl classpath. Replace directory
//     creation with plain PsiDirectory API calls — a real, correct implementation (not a stub),
//     since PsiDirectory.createSubdirectory/findSubdirectory is exactly what DirectoryUtil did
//     internally, just without the extra "select existing case-insensitively on Windows" handling
//     IDEA needs and NetBeans (Linux/macOS-first) does not.
def k2MoveTargetDescriptor = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/move/descriptor/K2MoveTargetDescriptor.kt')
if (k2MoveTargetDescriptor.exists()) {
  def text = k2MoveTargetDescriptor.text
  text = text.replace('import com.intellij.ide.util.DirectoryUtil\n', '')
  text = text.replace('import com.intellij.openapi.vfs.VfsUtilCore\n', '')
  text = text.replace(
'''        private fun findOrCreateSubdirectories(pkgPrefix: FqName): PsiDirectory {
            val pkgSuffix = pkgName.asString().removePrefix(pkgPrefix.asString()).removePrefix(".")
            val file = VfsUtilCore.findRelativeFile(pkgSuffix.replace('.', java.io.File.separatorChar), baseDirectory.virtualFile)
            if (file != null) return file.toPsiDirectory(baseDirectory.project) ?: error("Could not find directory $pkgName")
