'''        private fun findOrCreateSubdirectories(pkgPrefix: FqName): PsiDirectory {
            val pkgSuffix = pkgName.asString().removePrefix(pkgPrefix.asString()).removePrefix(".")
            var dir = baseDirectory
            if (pkgSuffix.isNotEmpty()) {
                for (segment in pkgSuffix.split('.')) {
                    dir = dir.findSubdirectory(segment) ?: dir.createSubdirectory(segment)
                }
            }
            return dir
        }'''
  )
  // addElementsToTarget()'s oldToNewMap only maps *nested* declarations of a moved element
  // (oldElement.withChildDeclarations(), which excludes the receiver itself) — real IDEA can get
  // away with this because MoveRenameUsageInfo.getReferencedElement() there re-resolves through a
  // document-synced smart pointer that keeps following the element across the move. This plugin's
  // simplified MoveRenameUsageInfo stub (Nbm, no PSI-document sync — see its own doc comment)
  // resolves referencedElement via a plain SmartPsiElementPointer, which does NOT follow a
  // PSI-tree relocation, so external usages of a moved *top-level* declaration (the common case:
  // a plain function/class with no nested declarations) would never be retargeted without also
  // mapping the moved element itself, not just its children.
  text = text.replace(
'''            elements.forEach { oldElement ->
                val movedElement = addElement(target, oldElement)
                if (movedElement is KtNamedDeclaration) {
                    // we assume that the children are in the same order before and after the move
                    for ((oldChild, newChild) in oldElement.withChildDeclarations().zip(movedElement.withChildDeclarations())) {
                        oldToNewMap[oldChild] = newChild
                    }
                }
