                listOfNames.addIfNotNull(symbol.javaGetterName.asString())
                listOfNames.addIfNotNull(symbol.javaSetterName?.asString())
            }
        }
    }

    // Add references to usages of this declaration using the Java facade names
    listOfNames.forEach(::addJavaFacadeUsages)

    return usages
}''',
'''// Non-code usages (Kdoc mentions, string-template mentions of the moved FqName) require a
// whole-project text-search engine (TextOccurrencesUtil) not available standalone; this only
// matters when the user opts in to "search in comments/strings/text", which IDEA itself defaults
