'''        return if (ApplicationManager.getApplication().isDispatchThread && !ApplicationManager.getApplication().isWriteAccessAllowed) {
            runWithModalProgressBlocking(
                c.project, KotlinBundle.message("fix.change.signature.prepare")
            ) { readAction { getCallable() } }
        } else {
            getCallable()
        }''',
'''        return getCallable()'''
  )
  text = text.replace('import com.intellij.openapi.application.ApplicationManager\n', '')
  text = text.replace('import com.intellij.openapi.application.readAction\n', '')
  text = text.replace('import com.intellij.platform.ide.progress.runWithModalProgressBlocking\n', '')
  changeSigMethodDescriptor.text = text
  log.info("Patched KotlinMethodDescriptor.kt: removed modal-progress branch (no EDT modal progress standalone)")
}

// 13. kotlinMembersNameConflicts.kt (E9.8): checkRedeclarationConflictsInInheritors uses
//     ClassInheritorsSearch (whole-project hierarchy index) — same limitation already accepted for
//     Move Declaration's functionOverriddenInSubclassConflict/sealedClassesConflict checks (no
//     project-wide inheritor index standalone). Made a no-op rather than falsely reporting/missing
//     conflicts.
def membersNameConflicts = new File(srcDir, 'org/jetbrains/kotlin/idea/refactoring/conflicts/kotlinMembersNameConflicts.kt')
if (membersNameConflicts.exists()) {
  def text = membersNameConflicts.text
  text = text.replace('import com.intellij.psi.search.searches.ClassInheritorsSearch\n', '')
  def fnMarker = 'private fun checkRedeclarationConflictsInInheritors(declaration: KtNamedDeclaration, newName: String, result: MutableList<UsageInfo>) {'
  def fnIdx = text.indexOf(fnMarker)
  if (fnIdx >= 0) {
    def bodyStart = text.indexOf('{', fnIdx) + 1
    // Find the matching closing brace by tracking nesting depth.
    def depth = 1
    def i = bodyStart
    while (depth > 0 && i < text.length()) {
      def ch = text.charAt(i)
      if (ch == '{' as char) depth++
      else if (ch == '}' as char) depth--
      i++
    }
    text = text.substring(0, bodyStart) + '\n    // No project-wide inheritor index standalone; same limitation as Move Declaration\'s\n    // hierarchy-based conflict checks (see docs/stubs.md).\n' + text.substring(i - 1)
  }
  membersNameConflicts.text = text
  log.info("Patched kotlinMembersNameConflicts.kt: made checkRedeclarationConflictsInInheritors a no-op (no inheritor index standalone)")
}

// 14. KotlinChangeSignatureConflictSearcher.kt (E9.8): drop the Java-interop conflict branches
//     (OverriderUsageInfo/MethodCallUsageInfo/JavaChangeSignatureUsageProcessor) — usageInfo is
//     never one of these types for a pure-Kotlin change (out of scope, see E9.8 strategy).
def changeSigConflictSearcher = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/changeSignature/KotlinChangeSignatureConflictSearcher.kt')
if (changeSigConflictSearcher.exists()) {
  def text = changeSigConflictSearcher.text
  text = text.replace('import com.intellij.refactoring.changeSignature.JavaChangeSignatureUsageProcessor\n', '')
  text = text.replace('import com.intellij.refactoring.changeSignature.MethodCallUsageInfo\n', '')
  text = text.replace('import com.intellij.refactoring.changeSignature.OverriderUsageInfo\n', '')
  text = text.replace(
'''                is OverriderUsageInfo -> {
                    JavaChangeSignatureUsageProcessor.ConflictSearcher.checkParametersToDelete(usageInfo.overridingMethod, parametersToRemove, result)
                }
                is MethodCallUsageInfo -> {
                    val conflictMessage = when {
                        hasDefaultParameter -> KotlinBundle.message("change.signature.conflict.text.kotlin.default.value.in.non.kotlin.files")
                        else -> continue
                    }

                    result.putValue(usageInfo.element, conflictMessage)
                }
''', '')
  changeSigConflictSearcher.text = text
  log.info("Patched KotlinChangeSignatureConflictSearcher.kt: dropped Java-interop conflict branches")
}

// 15. KotlinFunctionCallUsage.kt (E9.8): drop K2IntroduceVariableHandler.collectCandidateTargetContainersAndDoRefactoring
//     (Introduce Variable's IDE-action-system handler is not ported — the same "don't port handler
//     classes" convention as every other E9.x refactoring, see KaMoveDeclarationComputer not porting
//     K2MoveHandler.kt). It only fires when a default-value expression needs a temp variable
//     introduced (side-effect ordering edge case); skipping it leaves the expression substituted
//     inline instead of hoisted to a variable — a conservative simplification, not a correctness bug.
def functionCallUsage = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/changeSignature/usages/KotlinFunctionCallUsage.kt')
if (functionCallUsage.exists()) {
  def text = functionCallUsage.text
  text = text.replace('import org.jetbrains.kotlin.idea.k2.refactoring.introduce.introduceVariable.K2IntroduceVariableHandler\n', '')
  text = text.replace(
'''                allowAnalysisFromWriteAction {
                    allowAnalysisOnEdt {
                        K2IntroduceVariableHandler.collectCandidateTargetContainersAndDoRefactoring(
                            project, null, argumentExpression,
                            isVar = false,
                            occurrencesToReplace = listOf(argumentExpression),
                            onNonInteractiveFinish = {
                                argumentExpression = psiFactory.createExpression(it.name!!)
                            })
                    }
                }''',
'''                // K2IntroduceVariableHandler not ported (IDE-action-system handler); expression is
                // substituted inline instead of hoisted to a temp variable — see patch #15 in pom.xml.'''
  )
  functionCallUsage.text = text
  log.info("Patched KotlinFunctionCallUsage.kt: removed K2IntroduceVariableHandler temp-variable extraction")
}

// 17. KotlinChangeSignatureUsageSearcher.kt (E9.8): replace ReferencesSearch.search() (no-op
//     standalone, backed by NoOpPsiSearchHelper) with KotlinChangeSignatureUsageSearchService's
//     whole-project PSI scan — same call-site-patch strategy as patch #10's findReferences().
def changeSigUsageSearcher = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/changeSignature/KotlinChangeSignatureUsageSearcher.kt')
if (changeSigUsageSearcher.exists()) {
  def text = changeSigUsageSearcher.text
  text = text.replace(
    'for (reference in ReferencesSearch.search(oldParam, oldParam.useScope()).asIterable()) {',
    'for (reference in (KotlinChangeSignatureUsageSearchService.getInstance()?.findUsages(oldParam) ?: emptyList())) {'
  )
  text = text.replace(
    'ReferencesSearch.search(it).asIterable().mapNotNullTo(result) { reference ->',
    '(KotlinChangeSignatureUsageSearchService.getInstance()?.findUsages(it) ?: emptyList()).mapNotNullTo(result) { reference ->'
  )
  changeSigUsageSearcher.text = text
  log.info("Patched KotlinChangeSignatureUsageSearcher.kt: wired KotlinChangeSignatureUsageSearchService")
}

// 16. KotlinTypeInfo.kt (E9.8): errorIgnoringRenderer's custom KaErrorTypeRenderer calls
//     PrettyPrinter.append(String), which the era-253 analysis-api jar marks as a JetBrains-internal
//     API (compile error, not just a warning, under this Kotlin compiler version). Drop the custom
//     error-type rendering and fall back to the base renderer's default error-type text — a cosmetic
//     difference (slightly less pretty error-type strings), not a correctness change: this renderer
//     only affects the type-text shown for exotic/inference-error cases, not normal signatures.
def changeSigTypeInfo = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/changeSignature/KotlinTypeInfo.kt')
if (changeSigTypeInfo.exists()) {
  def text = changeSigTypeInfo.text
  text = text.replace(
'''@KaExperimentalApi
private val errorIgnoringRenderer: KaTypeRenderer = KaTypeRendererForSource.WITH_QUALIFIED_NAMES.with {
    errorTypeRenderer = object : KaErrorTypeRenderer {
        override fun renderType(
            analysisSession: KaSession,
            type: KaErrorType,
            typeRenderer: KaTypeRenderer,
            printer: PrettyPrinter
        ) {
            type.presentableText?.let {
                printer.append(it)
            }
        }
    }
}''',
'''@KaExperimentalApi
private val errorIgnoringRenderer: KaTypeRenderer = KaTypeRendererForSource.WITH_QUALIFIED_NAMES'''
  )
  changeSigTypeInfo.text = text
  log.info("Patched KotlinTypeInfo.kt: dropped custom errorTypeRenderer (PrettyPrinter.append is JetBrains-internal-only in this compiler version)")
}

// 17. KotlinChangeSignatureUsageProcessor.kt (E9.8): the "propagation" isCaller branch of
//     processParameterListWithStructuralChanges() unconditionally appends every new parameter to a
//     caller's own parameter list. This plugin's KaChangeSignatureComputer.withCallerPropagation()
//     marks *every* direct caller with a CallerUsageInfo (needed so that caller's own call site
//     still forwards the new argument via KotlinFunctionCallUsage.isCaller() — see that function's
//     KDoc), including a caller that already declares a same-named parameter from an earlier
//     propagation or a repeated invocation. Filter newParameters by name here so such a caller's
//     *own declaration* is left untouched, without dropping it from propagation entirely (which
//     would also silently stop its call site from forwarding the value).
def changeSigUsageProcessorDedup = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/changeSignature/KotlinChangeSignatureUsageProcessor.kt')
if (changeSigUsageProcessorDedup.exists()) {
  def text = changeSigUsageProcessorDedup.text
  text = text.replace(
    'val newParameters = changeInfo.newParameters.filter { it.isNewParameter }\n                    if (isNotEmpty() && newParameters.isNotEmpty()) {',
    'val existingNames = (element as? KtCallableDeclaration)?.valueParameters?.mapNotNull { it.name }?.toSet().orEmpty()\n                    val newParameters = changeInfo.newParameters.filter { it.isNewParameter && it.name !in existingNames }\n                    if (isNotEmpty() && newParameters.isNotEmpty()) {'
  )
  changeSigUsageProcessorDedup.text = text
  log.info("Patched KotlinChangeSignatureUsageProcessor.kt: caller-propagation skips parameters the caller already declares by name")
}

// 18. KotlinChangeSignatureUsageProcessor.kt (E9.8 M3): shortenReferences() throws for constructors
//     specifically, after a *structural* parameter-list change (add/remove/reorder — plain renames
//     are unaffected), with KotlinIllegalArgumentExceptionWithAttachments: "Error while resolving
//     FirConstructorImpl/FirPrimaryConstructor from ANNOTATION_ARGUMENTS to BODY_RESOLVE". Root
//     cause: `replaceListPsiAndKeepDelimiters`/`KtParameterList.replace()` swap in a brand-new
//     parameter-list PSI node via a raw, non-transactional PSI mutation — this plugin's standalone
//     `NoOpPomModel.runTransaction` (Nbm's `PomModel` stub) never fires the real "out-of-block
//     modification" notification a live IDE would, so the low-level FIR cache never gets a chance to
//     invalidate and rebuild the constructor's FIR node before shortenReferences() forces it to
//     BODY_RESOLVE phase. Functions apparently tolerate this stale-cache state; constructors do not.
//     A full fix would mean implementing real PomModel transaction semantics (well beyond this
//     plugin's standalone-container scope, same class of limitation as the accepted "no whole-project
//     inheritor index" stubs elsewhere). Reproduced even for the simplest possible constructor (no
//     supertype, no delegation, no default values) — not something introduced by this plugin's usage-
//     search additions. Wrapping both call sites in updatePrimaryMethod() so the refactoring still
//     succeeds, falling back to un-shortened, fully-qualified type names for the constructor's own
//     parameter list — the same accepted cosmetic-degradation strategy as KotlinTypeInfo.kt's
//     errorIgnoringRenderer patch above.
def changeSigUsageProcessorShorten = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/changeSignature/KotlinChangeSignatureUsageProcessor.kt')
if (changeSigUsageProcessorShorten.exists()) {
  def text = changeSigUsageProcessorShorten.text
  text = text.replace(
    '        shortenReferences(newParameterList)\n    }\n\n    private fun updateContextParametersList(',
    '        runCatching { shortenReferences(newParameterList) }\n    }\n\n    private fun updateContextParametersList('
  )
  text = text.replace(
    '        val parameterList = (element as? KtCallableDeclaration)?.valueParameterList\n        if (parameterList != null) {\n            shortenReferences(parameterList)\n        }\n    }',
    '        val parameterList = (element as? KtCallableDeclaration)?.valueParameterList\n        if (parameterList != null) {\n            runCatching { shortenReferences(parameterList) }\n        }\n    }'
  )
  changeSigUsageProcessorShorten.text = text
  log.info("Patched KotlinChangeSignatureUsageProcessor.kt: swallowed shortenReferences failure on constructors after a structural parameter-list change (falls back to fully-qualified type names)")
}
